import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import type { Post } from '@/lib/types'
import { ViewAllPostsButton } from './view-all-posts-button'

export const metadata: Metadata = {
  title: 'Home',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

// `cache: 'no-store'` keeps the request-time behaviour of the previous
// `getServerSideProps`: the data is fetched fresh on every request.
async function getRecentPosts(): Promise<Post[]> {
  const res = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  )

  if (!res.ok) {
    throw new Error(`Failed to fetch recent posts: ${res.status}`)
  }

  return res.json()
}

export default async function HomePage() {
  // `headers()` is async in Next.js 16 and replaces `getServerSideProps`'s `req`.
  const [posts, headerList] = await Promise.all([getRecentPosts(), headers()])
  const userAgent = headerList.get('user-agent') ?? ''
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <ViewAllPostsButton />
    </div>
  )
}

