'use client' // Error boundaries must be Client Components

import { useEffect } from 'react'

// Replaces `pages/_error.js` for errors thrown inside a route. Like the old
// `_error` page it renders inside the app chrome (the root layout), so the
// header and footer are preserved. There is no `statusCode` prop in the App
// Router — 404s are handled by `not-found.tsx` instead.
export default function Error({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    // Log the error to an error reporting service
    console.error(error)
  }, [error])

  return (
    <>
      {/* Error boundaries cannot export `metadata`, so use React's <title>. */}
      <title>Error - My Blog</title>

      <div className="error-page">
        <h1>An error occurred</h1>
        <p>Sorry, something went wrong.</p>
        <button onClick={() => retry()}>Try again</button>
      </div>
    </>
  )
}

