import type { NextRequest } from 'next/server'
import type { ApiPost, CreatePostBody } from '@/lib/types'

// Route Handlers replace `pages/api/posts/index.js`. Each HTTP method is its
// own exported function instead of a single handler branching on `req.method`,
// and Next.js answers unsupported methods with a 405 plus the `Allow` header
// automatically — so the old manual 405 branch is no longer needed.

export async function GET() {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: NextRequest) {
  let body: Partial<CreatePostBody>

  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

